# cfg_publish — makes the changes set since the last mark visible to get.
# cfg 2.x holds a change to an existing key back from get until the next mark,
# so this must run after the last cfg_set and before anything reads the values.
cfg_publish() {
  local out
  out=$(cfg_mark 2>&1) || { warn "mark failed ($out)"; return 1; }
  printf '%s' "$out"
}

